            animation: fadeOut 0.5s ease-out 2s both;
        }

        .loading-spinner {
            width: 50px;
            height: 50px;
            border: 3px solid rgba(255, 255, 255, 0.3);
            border-top: 3px solid white;
            border-radius: 50%;
            animation: spin 1s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        @keyframes fadeOut {
            to {
                opacity: 0;
                visibility: hidden;
            }
        }
    </style>
</head>
<body>
    <!-- Loading Screen -->
    <div class="loading">
        <div class="loading-spinner"></div>
    </div>

    <!-- Animated Background -->
    <div class="background"></div>

    <!-- Floating Particles -->
    <div class="particles">
        <div class="particle"></div>
        <div class="particle"></div>
        <div class="particle"></div>
        <div class="particle"></div>
        <div class="particle"></div>
        <div class="particle"></div>
    </div>

    <!-- Navigation -->
    <nav class="navbar">
        <a href="#" class="logo">
            <i class="fas fa-parking"></i>
            Slotify
        </a>
        <div class="nav-links">
            <a href="/" class="nav-link">Home</a>
            <a href="/about/" class="nav-link">About</a>
            <a href="/features/" class="nav-link">Features</a>
            <a href="/contact/" class="nav-link">Contact</a>
        </div>
    </nav>

    <!-- Main Content -->
    <div class="container">
        <div class="content">
            <h1>Slotify</h1>
            <p class="subtitle">Easily find available free parking spots with our smart parking solution</p>

            <div class="features">
                <div class="feature">
                    <i class="fas fa-search"></i>
                    <span>Quick Search</span>
                </div>
                <div class="feature">
                    <i class="fas fa-dollar-sign"></i>
                    <span>Best Prices</span>
                </div>
                <div class="feature">
                    <i class="fas fa-shield-alt"></i>
                    <span>Secure Booking</span>
                </div>
            </div>

            <div class="buttons">
                <a href="/userRegister/" class="button btn-primary">
                    <i class="fas fa-user-plus"></i>
                    Register Now
                </a>
                <a href="/userSignIn/" class="button btn-secondary">
                    <i class="fas fa-sign-in-alt"></i>
                    Sign In
                </a>
            </div>
        </div>
    </div>

    <!-- Stats Section -->
    <div class="stats">
        <div class="stat">
            <span class="stat-number" id="ownersCount">Loading...</span>
            <span class="stat-label">Happy Lot Owners</span>
        </div>
        <div class="stat">
            <span class="stat-number" id="parkingLotCount">Loading...</span>
            <span class="stat-label">Parking Lots</span>
        </div>
        <div class="stat">
            <span class="stat-number">24/7</span>
            <span class="stat-label">Support</span>
        </div>
    </div>


    <script>
document.addEventListener('DOMContentLoaded', function () {
    const statNumbers = document.querySelectorAll('.stat-number');

    // Particle animation enhancement
    const particles = document.querySelectorAll('.particle');
    particles.forEach(particle => {
        const randomDelay = Math.random() * 6;
        particle.style.animationDelay = randomDelay + 's';
        particle.style.top = '100vh';
    });

    // Button click effects
    const buttons = document.querySelectorAll('.button');
    buttons.forEach(button => {
        button.addEventListener('click', function (e) {
            const ripple = document.createElement('span');
            const rect = this.getBoundingClientRect();
            const size = Math.max(rect.width, rect.height);
            const x = e.clientX - rect.left - size / 2;
            const y = e.clientY - rect.top - size / 2;

            ripple.style.cssText = `
                position: absolute;
                width: ${size}px;
                height: ${size}px;
                left: ${x}px;
                top: ${y}px;
                background: rgba(255, 255, 255, 0.3);
                border-radius: 50%;
                transform: scale(0);
                animation: ripple 0.6s linear;
                pointer-events: none;
            `;

            this.appendChild(ripple);
            setTimeout(() => ripple.remove(), 600);
        });
    });

    // Parallax effect on mouse move
    document.addEventListener('mousemove', function (e) {
        const mouseX = e.clientX / window.innerWidth;
        const mouseY = e.clientY / window.innerHeight;

        particles.forEach((particle, index) => {
            const speed = (index + 1) * 0.5;
            const x = (mouseX - 0.5) * speed;
            const y = (mouseY - 0.5) * speed;
            particle.style.transform = `translate(${x}px, ${y}px)`;
        });
    });

    // Animate Number Helper
    const animateNumber = (element, start, end, suffix) => {
        const duration = 2000;
        const increment = (end - start) / (duration / 16);
        let current = start;

        const timer = setInterval(() => {
            current += increment;
            if (current >= end) {
                current = end;
                clearInterval(timer);
            }
            element.textContent = Math.floor(current) + suffix;
        }, 16);
    };

    // Fetch stats and animate with real data
    fetch('/getLandingPageStats/')
        .then(response => {
            if (!response.ok) {
                throw new Error('Network response was not OK');
            }
            return response.json();
        })
        .then(data => {
            // Animate with real values
            const ownersElement = document.getElementById('ownersCount');
            const parkingElement = document.getElementById('parkingLotCount');

            // Delay animation start for smooth page load
            setTimeout(() => {
                animateNumber(ownersElement, 0, data.owners_count, '+');
                animateNumber(parkingElement, 0, data.parking_lot_count, '+');
            }, 2500);
        })
        .catch(error => {
            console.error('Error fetching stats:', error);
            document.getElementById('ownersCount').textContent = 'N/A';
            document.getElementById('parkingLotCount').textContent = 'N/A';
        });

    // Inject ripple animation CSS
    const style = document.createElement('style');
    style.textContent = `
        @keyframes ripple {
            to {
                transform: scale(2);
                opacity: 0;
            }
        }
    `;
    document.head.appendChild(style);
});
    </script>
</body>
</html>'
